<script setup lang="ts">
import {computed} from 'vue'
import {Activity,Database,ExternalLink,Gauge,HardDrive,Timer} from '@lucide/vue'
import {bytes,type Summary} from '../services/api'
const props=defineProps<{summary:Summary}>(),emit=defineEmits<{open:[]}>()
const data=(key:string)=>props.summary[key]?.status==='available'?props.summary[key]?.data:undefined
const sd=computed(()=>data('sd')),storage=computed(()=>data('internalStorage'))
const byteText=(value:unknown)=>typeof value==='string'&&/^\d+$/.test(value)?bytes(value):'—'
const uptime=computed(()=>{const seconds=data('uptime');if(typeof seconds!=='number'||!Number.isFinite(seconds)||seconds<0)return '—';const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60);return `${days?days+'日 ':''}${hours||days?hours+'時間 ':''}${minutes}分`})
const loads=computed(()=>{const raw=data('load');if(typeof raw!=='string')return [null,null,null];const values=raw.trim().split(/\s+/).slice(0,3).map(Number);return values.length===3?values.map(value=>Number.isFinite(value)&&value>=0?value:null):[null,null,null]})
const percentage=(value:unknown)=>typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100?value:null
</script>
<template>
 <section class="panel device-status" aria-label="本体の状態"><div class="hero-head"><h2><Gauge :size="20"/>本体の状態</h2><button class="icon-button section-link" aria-label="本体の詳細を開く" @click="emit('open')"><ExternalLink :size="18"/></button></div><div class="device-uptime"><Timer :size="21"/><span>稼働時間</span><strong>{{uptime}}</strong></div><div class="device-load"><div><Activity :size="21"/><span>Load average</span></div><dl><div v-for="(value,index) in loads" :key="index"><dt>{{[1,5,15][index]}}分</dt><dd>{{value===null?'—':value.toFixed(2)}}</dd></div></dl></div><div class="device-storage"><div><HardDrive :size="21"/><strong>SDカード</strong><span class="device-capacity">残り {{byteText(sd?.freeBytes)}} / {{byteText(sd?.totalBytes)}}</span><b>{{percentage(sd?.usedPercent)===null?'':Math.round(sd.usedPercent)+'% 使用'}}</b></div><progress v-if="percentage(sd?.usedPercent)!==null" max="100" :value="sd.usedPercent" aria-label="SDカード使用率"></progress></div><div class="device-storage"><div><Database :size="21"/><strong>本体空き容量</strong><span class="device-capacity">{{byteText(storage?.freeBytes)}} / {{byteText(storage?.totalBytes)}}</span></div><progress v-if="percentage(storage?.usedPercent)!==null" max="100" :value="storage.usedPercent" aria-label="本体ストレージ使用率"></progress></div></section>
</template>
<style scoped>
.device-status{min-width:0;overflow:hidden;align-self:start}.device-uptime{display:flex;align-items:center;gap:12px;padding:14px 18px;font-size:12px;color:var(--muted)}.device-uptime strong{color:var(--text);margin-left:auto;font-size:21px;font-weight:600;font-variant-numeric:tabular-nums}.device-storage{border-top:1px solid var(--line);padding:16px 18px}.device-storage>div{display:flex;align-items:center;gap:8px;font-size:12px;flex-wrap:wrap}.device-storage svg{color:var(--muted)}.device-storage strong{font-weight:600}.device-storage b{margin-left:auto;font-size:12px;white-space:nowrap;font-weight:600}.device-capacity{font-size:11px;color:var(--muted);white-space:nowrap}.device-storage strong{white-space:nowrap}.device-storage progress{display:block;width:100%;height:4px;accent-color:var(--accent);margin-top:12px;border:0;border-radius:3px;overflow:hidden}.device-storage progress::-webkit-progress-bar{background:var(--bg)}.device-storage progress::-webkit-progress-value{background:var(--accent)}@media(max-width:600px){.device-storage{padding:16px 20px}.device-uptime{padding:0 20px 18px}.device-uptime strong{font-size:19px}}
</style>
<style scoped>
.device-load{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line);padding:12px 18px}.device-load>div{display:flex;align-items:center;gap:12px;font-size:12px;color:var(--muted)}.device-load dl{display:flex;gap:22px;margin:0;font-variant-numeric:tabular-nums}.device-load dl>div{display:grid;gap:5px;text-align:right}.device-load dt{font-size:11px;color:var(--muted)}.device-load dd{font-size:17px;font-weight:600;margin:0}@media(max-width:600px){.device-load{padding:16px 20px}.device-load dl{gap:18px;margin-left:auto}}
</style>
